def topo_sort(graph):
    # Collect all nodes (keys and values)
    nodes = set()
    for u, deps in graph.items():
        nodes.add(u)
        for v in deps:
            nodes.add(v)

    # Build adjacency list: node -> list of nodes that depend on it
    adj = {node: [] for node in nodes}
    indeg = {node: 0 for node in nodes}

    for u, deps in graph.items():
        for v in deps:
            adj[v].append(u)
            indeg[u] += 1

    # Kahn's algorithm
    queue = [n for n in nodes if indeg[n] == 0]
    order = []

    while queue:
        node = queue.pop(0)          # pop from front (simple list queue)
        order.append(node)
        for nb in adj[node]:
            indeg[nb] -= 1
            if indeg[nb] == 0:
                queue.append(nb)

    if len(order) != len(nodes):
        return None                 # cycle detected

    return order

```

