def parse_csv(text):
    lines = text.strip().splitlines()
    if not lines:
        return []

    header = [h.strip() for h in lines[0].split(',')]
    result = []

    def split_line(line):
        fields = []
        current = []
        i = 0
        while i < len(line):
            ch = line[i]
            if ch == '"':
                # start of a quoted field
                current.append('"')
                i += 1
                while i < len(line):
                    if line[i] == '"':
                        if i + 1 < len(line) and line[i+1] == '"':
                            current.append('"')
                            i += 2
                        else:
                            # end of quoted field
                            i += 1
                            break
                    else:
                        current.append(line[i])
                        i += 1
                # after the closing quote, expect comma or end of line
                if i < len(line) and line[i] == ',':
                    i += 1
                # skip possible trailing spaces after comma (handled by strip on next field)
            elif ch == ',':
                fields.append(''.join(current).strip())
                current = []
                i += 1
            else:
                current.append(ch)
                i += 1
        fields.append(''.join(current).strip())
        return fields

    for line in lines[1:]:
        if not line.strip():
            continue
        values = split_line(line)
        row = {}
        for h, v in zip(header, values):
            row[h] = v
        result.append(row)

    return result

```

