def normalize(path):
    # Determine if the path is absolute (starts with '/')
    is_absolute = path.startswith('/')

    # Split by '/' and filter out empty strings and '.'
    parts = [p for p in path.split('/') if p != '' and p != '.']

    # Resolve '..' components
    resolved = []
    for part in parts:
        if part == '..':
            if resolved:
                resolved.pop()
            # If the path is relative and we try to go above root, ignore it
            # (for absolute paths, .. at root just stays at root)
        else:
            resolved.append(part)

    # Reconstruct the path
    if is_absolute:
        # Absolute path: always start with '/'
        result = '/' + '/'.join(resolved)
        # If result is empty (e.g., path was "/.." or "/."), return '/'
        if not result.strip('/'):
            return '/'
        return result
    else:
        # Relative path
        if not resolved:
            return '.'
        return '/'.join(resolved)

```

