def merge_dicts(a, b):
    result = {}
    for key in set(list(a.keys()) + list(b.keys())):
        if key in a and key in b:
            va, vb = a[key], b[key]
            if isinstance(va, dict) and isinstance(vb, dict):
                result[key] = merge_dicts(va, vb)
            else:
                result[key] = vb
        elif key in a:
            result[key] = a[key]
        else:
            result[key] = b[key]
    return result

