def human_bytes(n):
    if n < 1024:
        return f"{n} B"
    units = ["KiB", "MiB", "GiB", "TiB"]
    for i, unit in enumerate(units):
        divisor = 1024 ** (i + 1)
        value = n / divisor
        if value < 1024:
            return f"{value:.1f} {unit}"
    # Fallback for values >= TiB (should not occur with typical usage)
    return f"{n / (1024**4):.1f} TiB"

