import re

def parse_duration(s):
    if not isinstance(s, str) or not s:
        raise ValueError("Invalid duration string")

    total = 0
    # Match optional sign followed by number and unit (h, m, s, d)
    pattern = r'^([+-]?\d+)(h|m|s|d)$'
    matches = re.findall(pattern, s)

    if not matches:
        raise ValueError("Invalid duration string")

    for value_str, unit in matches:
        try:
            value = int(value_str)
        except ValueError:
            raise ValueError("Invalid duration string")

        multiplier = 1
        if unit == 'h':
            multiplier = 3600
        elif unit == 'm':
            multiplier = 60
        elif unit == 's':
            multiplier = 1
        elif unit == 'd':
            multiplier = 86400

        total += value * multiplier

    return total
```

