import hashlib

def stable_hash(obj):
    if isinstance(obj, dict):
        # Sort keys and recursively hash each value
        items = sorted((k, stable_hash(v)) for k, v in obj.items())
        data = "".join(f"{k}:{v}" for k, v in items)
        return hashlib.sha256(data.encode("utf-8")).hexdigest()
    elif isinstance(obj, list):
        # Hash each element in order
        data = "".join(stable_hash(v) for v in obj)
        return hashlib.sha256(data.encode("utf-8")).hexdigest()
    elif isinstance(obj, str):
        return hashlib.sha256(obj.encode("utf-8")).hexdigest()
    elif isinstance(obj, int):
        return hashlib.sha256(str(obj).encode("utf-8")).hexdigest()
    else:
        # Fallback for other types (e.g., float, bool)
        return hashlib.sha256(repr(obj).encode("utf-8")).hexdigest()
