function debounceCount(fn, ms) {
  let timeout;
  let callCount = 0;

  const debounced = function (...args) {
    clearTimeout(timeout);
    callCount++;
    timeout = setTimeout(() => {
      fn.apply(this, args);
    }, ms);
  };

  debounced.flush = function () {
    clearTimeout(timeout);
    if (callCount > 0) {
      fn.call(this);
      callCount = 0;
    }
  };

  return { call: debounced, flush: debounced.flush };
}

module.exports = debounceCount;
```

