import { useRef } from 'react';

export function debounceState<T extends (...args: any[]) => void>(fn: T, wait: number): {
  pending: boolean;
  mark: () => void;
  clear: () => void;
} {
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  let resolvePending: ((...args: Parameters<T>) => void) | undefined;

  const mark = (): void => {
    if (!timer.current) return;
    clearTimeout(timer.current);
    timer.current = setTimeout(() => {
      timer.current = null;
      resolvePending?.();
      resolvePending = undefined;
    }, wait);
  };

  const clear = (): void => {
    if (timer.current) {
      clearTimeout(timer.current);
      timer.current = null;
    }
  };

  return {
    pending: !!timer.current,
    mark,
    clear,
  };
}
```

