import React, { useState } from 'react';
import { View, Text, FlatList, ActivityIndicator, StyleSheet } from 'react-native';

const DataItem = ({ item }) => (
  <View style={styles.item}>
    <Text>{item}</Text>
  </View>
);

export const InfiniteScrollExample = () => {
  const [dataSource, setDataSource] = useState([]);
  const [page, setPage] = useState(1);
  const fetchMoreData = async () => {
    // Simulate API call
    await new Promise(resolve => setTimeout(resolve, 500));
    const newItems = Array.from({ length: 10 }, (_, i) => `Item ${page * 10 + i}`);
    setDataSource(prev => [...prev, ...newItems]);
    setPage(prev => prev + 1);
  };

  return (
    <FlatList
      data={dataSource}
      renderItem={({ item }) => <DataItem item={item} />}
      keyExtractor={(item, index) => index.toString()}
      onEndReached={fetchMoreData}
      onEndReachedThreshold={0.5}
      showsVerticalScrollIndicator={false}
    >
      <ActivityIndicator size="small" color="#fff" style={{ position: 'absolute', bottom: 20 }} />
    </FlatList>
  );
};

const styles = StyleSheet.create({
  item: {
    padding: 20,
    borderBottomWidth: StyleSheet.hairlineWidth,
    borderColor: '#ccc',
  },
});
